import {lazy,useCallback,useState} from 'react';
const OrderServices=lazy(()=>import('./Services').then(m=>({default:m.OrderServices})));
import {Drawer,Field,Form,Status} from './ui';
import {Blank,Feedback,QR,Scanner,Section} from './common';
import {platform,useResource,money,timestamp} from './data';

export function OrderDetail({id,role,onClose,onChange}){
 const r=useResource(()=>platform(`/orders/${id}`),[id]),[receipt,setReceipt]=useState(null),[notice,setNotice]=useState('');
 const act=useCallback(async(action,body={})=>{await platform(`/orders/${id}/${action}`,'POST',body);setNotice('Order updated.');await r.refresh();await onChange();},[id,r.refresh,onChange]);
 const scanOrganization=useCallback(token=>act('organization-scan',{token}),[act]);const scanDelivery=useCallback(token=>act('complete',{token}),[act]);const o=r.data?.order;
 return <Drawer title="Order details" onClose={onClose}><Feedback resource={r}/>{o?<><p className="small order-id">{o.id}</p><Status value={o.state}/><p className="notice">Sandbox order. No real funds are collected. Delivery rates and provider integration are not configured.</p><dl className="detail-list"><div><dt>Product payment</dt><dd>{o.productPayment.replaceAll('_',' ')}</dd></div><div><dt>Delivery payment</dt><dd>{o.deliveryPayment.replaceAll('_',' ')}</dd></div><div><dt>Ready</dt><dd>{o.ready?'Yes':'Awaiting preparation'}</dd></div><div><dt>Organization QR</dt><dd>{o.orgScanned?'Verified':'Not verified'}</dd></div><div><dt>Handoff</dt><dd>{o.handoff?'Confirmed':'Awaiting confirmation'}</dd></div></dl><ol className="order-progress" aria-label="Order progress">{[['placed',o.state==='placed'?'Placed':'Reserved'],['ready','Ready'],['picked_up','Picked up'],['delivered','Delivered']].map(([state,label],index)=>{const step=o.state==='delivered'?3:o.state==='picked_up'?2:o.ready?1:0;return <li key={state} className={index<=step?'complete':''} aria-current={index===step?'step':undefined}><span>{String(index+1).padStart(2,'0')}</span>{label}</li>;})}</ol><h3>Items</h3><ul className="line-list">{o.lines.map(line=><li key={line.product_id}><span className="order-line-product">{line.image?<img src={line.image} alt=""/>:<span className="order-line-placeholder" aria-hidden="true">▧</span>}<span>{line.name} × {line.quantity}</span></span><strong>{money(line.unit_price*line.quantity,o.currency)}</strong></li>)}</ul><p><strong>Product total {money(o.productTotal,o.currency)}</strong></p><h3>Delivery destination</h3><p>{o.address}</p>
 {['manager','dispatch'].includes(role)?<section className="order-actions"><h3>Prepare and hand off</h3>{!o.ready&&['placed','reserved'].includes(o.state)?<Form submit="Mark Ready" onSubmit={()=>act('ready')}/>:null}{o.organizationQr&&o.state!=='delivered'?<QR token={o.organizationQr} label="Organization pickup QR"/>:null}{!o.handoff&&o.ready&&o.orgScanned&&o.state==='reserved'?<Form submit="Confirm Handoff" onSubmit={()=>act('handoff')}/>:null}<p className="small muted">Pickup requires Ready, the assigned rider's QR scan, and your explicit Confirm Handoff.</p></section>:null}
 {role==='rider'&&o.state==='reserved'?<section className="order-actions"><h3>Verify pickup</h3><Scanner onScan={scanOrganization}/><Form submit="Verify organization QR token" onSubmit={d=>act('organization-scan',d)}><Field label="Organization QR token" name="token" required maxLength={200}/></Form>{o.ready&&o.handoff&&o.orgScanned?<Form submit="Confirm pickup" onSubmit={()=>act('pickup')}/>:<p className="small muted">Waiting for Ready, organization scan, and Confirm Handoff.</p>}<Form submit="Release reservation" onSubmit={()=>act('release')}/></section>:null}
 {role==='rider'&&o.state==='picked_up'?<section className="order-actions"><h3>Safe delivery</h3>{o.deliveryPayment==='cash_due'?<Form submit="Confirm cash received" onSubmit={d=>act('cash-confirm',d)}><Field label="Separate cash confirmation code" name="code" inputMode="numeric" pattern="[0-9]{5}" required maxLength={5}/></Form>:null}<Form submit="Verify delivery code" onSubmit={d=>act('delivery-code',d)}><Field label="Customer five-digit delivery code" name="code" inputMode="numeric" pattern="[0-9]{5}" required maxLength={5}/></Form>{o.deliveryQr?<QR token={o.deliveryQr} label="Customer scans this delivery QR"/>:null}</section>:null}
 {role==='consumer'&&o.state!=='delivered'?<section className="order-actions"><h3>Your delivery verification</h3><p>Share these codes only at your destination with your assigned rider.</p><dl className="detail-list"><div><dt>Delivery code</dt><dd className="verification-code">{o.deliveryCode}</dd></div>{o.cashCode?<div><dt>Cash payment code</dt><dd className="verification-code">{o.cashCode}</dd></div>:null}</dl>{o.state==='picked_up'?<><Scanner onScan={scanDelivery}/><Form submit="Confirm delivery QR" onSubmit={d=>act('complete',d)}><Field label="Token from rider delivery QR" name="token" required maxLength={200}/></Form></>:<p className="small muted">Scan the rider's order-specific QR after the rider verifies your delivery code.</p>}</section>:null}
 <OrderServices id={o.id} role={role}/>{notice?<p role="status" className="notice">{notice}</p>:null}<Form submit="View combined receipt" onSubmit={async()=>setReceipt((await platform(`/orders/${id}/receipt`)).receipt)}/>{receipt?<section className="receipt"><h3>Combined order receipt</h3><div className="receipt-part"><span className="small">RECEIPT A · PRODUCTS</span><h3>{money(receipt.productTotal,receipt.currency)}</h3><p>Product payment</p></div><div className="receipt-part"><span className="small">RECEIPT B · DELIVERY</span><h3>Amount not configured</h3><p>{receipt.deliveryNote}</p></div><p className="small">Product and delivery payments remain separate on this single order.</p></section>:null}</>:null}</Drawer>;
}
export default function Orders({role='consumer',compact=false}){
 const r=useResource(()=>platform('/orders')),[selected,setSelected]=useState(null),[error,setError]=useState('');
 const reserve=async id=>{try{setError('');await platform(`/orders/${id}/reserve`,'POST',{});setSelected(id);await r.refresh();}catch(e){setError(e.message);}};
 return <>{!compact?<><h1>{role==='rider'?'Your next delivery starts here.':role==='dispatch'?'Every handoff, in view.':'Every order, connected.'}</h1><p className="muted">{role==='rider'?'Approved riders can reserve available jobs. First successful server confirmation wins.':role==='dispatch'?'Monitor your organization orders and verify pickup handoffs.':'Your order history and delivery verification.'}</p></>:null}<Feedback resource={r}/>{error?<p role="alert" className="error">{error}</p>:null}{r.data?<Section title={role==='rider'?'Delivery jobs':compact?'Your orders':role==='dispatch'?'Dispatch queue':'Orders'} action={<button className="secondary" onClick={r.refresh}>Refresh</button>}><div className="table-wrap"><table><thead><tr><th>Order</th><th>Organization</th><th>Items</th><th>Product total</th><th>Created</th><th>Status</th><th><span className="sr-only">Action</span></th></tr></thead><tbody>{r.data.orders.map(o=>{let previews=[];try{previews=JSON.parse(o.item_previews||'[]');}catch{}return <tr key={o.id}><td className="order-id">{o.id.slice(0,8)}</td><td>{o.organization_name??o.organization_id.slice(0,8)}</td><td><div className="order-thumbnails" aria-label={`Items in order ${o.id.slice(0,8)}`}>{previews.slice(0,3).map((item,i)=>item.image?<img key={i} src={item.image} alt={item.name} title={`${item.name} × ${item.quantity}`}/>:<span key={i} title={`${item.name} × ${item.quantity}`} aria-label={item.name}>▧</span>)}</div></td><td>{money(o.product_total,o.currency)}</td><td>{timestamp(o.created_at)}</td><td><Status value={o.state}/>{o.ready?<small className="ready-label">Ready</small>:null}</td><td>{role==='rider'&&!o.rider_id&&o.state==='placed'?<button className="text-button" onClick={()=>reserve(o.id)}>Reserve job</button>:<button className="text-button" onClick={()=>setSelected(o.id)}>View order</button>}</td></tr>})}</tbody></table>{!r.data.orders.length?<Blank title={role==='rider'?'No delivery jobs available.':'No orders yet.'}>{role==='rider'?'Complete rider onboarding and approval to receive eligible jobs.':'Orders appear here when a customer places one.'}</Blank>:null}</div></Section>:null}{selected?<OrderDetail id={selected} role={role} onClose={()=>setSelected(null)} onChange={r.refresh}/>:null}</>;
}
